def calculate_totals(entries):
    total = 0.0
    failed_ids = []
    for entry in entries:
        try:
            _ = entry['id']
            total += entry['amount'] * entry['quantity']
        except (KeyError, TypeError):
            if isinstance(entry, dict) and 'id' in entry:
                failed_ids.append(entry['id'])
    return (total, failed_ids)
